-- V39__oauth2_user_identities.sql
-- Security: OAuth2 & Social Login (Google & GitHub)
-- Hỗ trợ tài khoản đăng nhập bên thứ ba và liên kết đa danh tính

-- 1. Cho phép password_hash NULL đối với người dùng đăng ký/đăng nhập qua Social Login
ALTER TABLE "users" ALTER COLUMN "password_hash" DROP NOT NULL;

-- 2. Tạo bảng user_identities lưu trữ liên kết tài khoản OAuth2
CREATE TABLE IF NOT EXISTS "user_identities" (
    "id"                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id"           BIGINT NOT NULL,
    "provider"          VARCHAR(32) NOT NULL,
    "provider_subject"  VARCHAR(255) NOT NULL,
    "email"             VARCHAR(255),
    "created_at"        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    "last_login_at"     TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "fk_user_identities_user" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE,
    CONSTRAINT "uk_user_identities_provider_subject" UNIQUE ("provider", "provider_subject")
);

-- 3. Chỉ mục phục vụ tra cứu
CREATE INDEX IF NOT EXISTS "idx_user_identities_user_id" ON "user_identities"("user_id");
CREATE INDEX IF NOT EXISTS "idx_user_identities_provider_email" ON "user_identities"("provider", "email");
